Object.assign(SNIP,{"l34syn": "class NhanVien {                         // lớp cha (base class)\nprotected:                               // lớp con dùng được, bên ngoài thì không\n    string ten;\n    double luong;\npublic:\n    NhanVien(string t, double l) : ten(t), luong(l) {}\n    double thuNhap() const { return luong; }\n    void gioiThieu() const { cout << ten << \"\\n\"; }\n};\n\nclass QuanLy : public NhanVien {         // QuanLy LÀ MỘT NhanVien\n    double phuCap;                       // thêm thành viên riêng\npublic:\n    QuanLy(string t, double l, double p) : NhanVien(t, l), phuCap(p) {}\n    double thuNhap() const {             // viết lại hàm của lớp cha\n        return NhanVien::thuNhap() + phuCap;\n    }\n};\nQuanLy q(\"Ha\", 20, 5);\nq.gioiThieu();          // hàm thừa kế từ NhanVien\ncout << q.thuNhap();    // 25: hàm của QuanLy"});PRESET_NOTES["l34"]={"Ví dụ: Lớp con dùng lại thành viên của lớp cha": "b có đủ ten, luong (phần NhanVien) và phuCap. gioiThieu không viết lại nên b dùng bản của NhanVien; thuNhap được viết lại và gọi NhanVien::thuNhap() rồi cộng phụ cấp. QuanLy lớn hơn NhanVien đúng 8 byte của phuCap.", "Ví dụ: Thứ tự tạo và hủy": "Tạo: hàm tạo Cho gọi DongVat(t) trước tiên (phần cha xong trước), rồi gán tuoi, rồi mới chạy thân hàm tạo Cho. Hủy: ngược lại, thân ~Cho chạy trước, ~DongVat sau cùng.", "Ví dụ: protected": "soDu là protected: hàm cuoiThang của lớp con TietKiem sửa được nó, nhưng main thì không (main phải dùng laySoDu). Nếu soDu là private, chính lớp con cũng không dùng được.", "Ví dụ: Con trỏ lớp cha trỏ tới đối tượng con": "p và r có kiểu Hinh nên p->ten() và r.ten() gọi Hinh::ten(), dù thật ra chúng đang chỉ tới một Tron. Trình biên dịch chọn hàm theo kiểu khai báo. Bài 35 dùng virtual để hàm được chọn theo đối tượng thật.", "Lỗi: quên public khi kế thừa": "Với class, kế thừa mặc định là private, nên các hàm public của DongVat trở thành private trong Meo: g++ báo 'void DongVat::an() const' is inaccessible within this context. Sửa: class Meo : public DongVat { };.", "Lỗi: lớp con dùng thành viên private của lớp cha": "soDu là private của TaiKhoan, nên ngay cả lớp con TietKiem cũng không sửa được: 'long long int TaiKhoan::soDu' is private within this context. Đổi soDu sang protected, hoặc cho TaiKhoan một hàm protected để lớp con dùng."};EX_HINTS["l34"]=[["Hinh không có hàm tạo mặc định nên hàm tạo HinhTron bắt buộc gọi Hinh(\"Hinh tron\") trong danh sách khởi tạo.", "Đặt tên tham số khác tên thành viên (bk) cho dễ đọc: : Hinh(\"Hinh tron\"), r(bk)."], ["QuanLy::thuNhap gọi NhanVien::thuNhap() rồi cộng phụ cấp: không lặp lại mã của lớp cha.", "layTen là hàm public của NhanVien nên QuanLy dùng được ngay mà không phải viết lại."], ["cuoiThang là hàm của TietKiem nhưng sửa được soDu vì soDu là protected trong TaiKhoan.", "nap, rut, laySoDu được thừa kế nguyên vẹn, không cần viết lại."]];
/* ===================== BÀI 34 · Kế thừa ===================== */
/* Bài 34 · Kế thừa
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P34=[{label:"Ví dụ: Lớp con dùng lại thành viên của lớp cha",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass NhanVien {\nprotected:\n    string ten;\n    double luong;\npublic:\n    NhanVien(string t, double l) : ten(t), luong(l) {}\n    void gioiThieu() const {\n        cout << \"Toi la \" << ten << \"\\n\";\n    }\n    double thuNhap() const {\n        return luong;\n    }\n};\n\nclass QuanLy : public NhanVien {\n    double phuCap;\npublic:\n    QuanLy(string t, double l, double p) : NhanVien(t, l), phuCap(p) {}\n    double thuNhap() const {\n        return NhanVien::thuNhap() + phuCap;\n    }\n};\n\nint main() {\n    NhanVien a(\"An\", 12);\n    QuanLy b(\"Ha\", 20, 5);\n    a.gioiThieu();\n    b.gioiThieu();\n    cout << a.thuNhap() << \" \" << b.thuNhap() << \"\\n\";\n    cout << sizeof(NhanVien) << \" \" << sizeof(QuanLy) << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Thứ tự tạo và hủy",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass DongVat {\nprotected:\n    string ten;\npublic:\n    DongVat(string t) : ten(t) {\n        cout << \"Tao DongVat \" << ten << \"\\n\";\n    }\n    ~DongVat() {\n        cout << \"Huy DongVat \" << ten << \"\\n\";\n    }\n};\n\nclass Cho : public DongVat {\n    int tuoi;\npublic:\n    Cho(string t, int a) : DongVat(t), tuoi(a) {\n        cout << \"Tao Cho \" << tuoi << \" tuoi\\n\";\n    }\n    ~Cho() {\n        cout << \"Huy Cho\\n\";\n    }\n};\n\nint main() {\n    Cho c(\"Milu\", 3);\n    cout << \"-- dang dung --\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: protected",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\nprotected:\n    long long soDu;\npublic:\n    TaiKhoan(long long s) : soDu(s) {}\n    long long laySoDu() const {\n        return soDu;\n    }\n};\n\nclass TietKiem : public TaiKhoan {\n    double laiSuat;\npublic:\n    TietKiem(long long s, double ls) : TaiKhoan(s), laiSuat(ls) {}\n    void cuoiThang() {\n        soDu += (long long)(soDu * laiSuat);\n    }\n};\n\nint main() {\n    TietKiem t(1000000, 0.005);\n    t.cuoiThang();\n    t.cuoiThang();\n    cout << t.laySoDu() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Con trỏ lớp cha trỏ tới đối tượng con",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    string ten() const {\n        return \"hinh chung\";\n    }\n};\n\nclass Tron : public Hinh {\npublic:\n    string ten() const {\n        return \"hinh tron\";\n    }\n};\n\nint main() {\n    Tron t;\n    Hinh* p = &t;\n    Hinh& r = t;\n    cout << t.ten() << \"\\n\";\n    cout << p->ten() << \"\\n\";\n    cout << r.ten() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: quên public khi kế thừa",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass DongVat {\npublic:\n    void an() const {\n        cout << \"An\\n\";\n    }\n};\n\nclass Meo : DongVat {\n};\n\nint main() {\n    Meo m;\n    m.an();\n    return 0;\n}"},{label:"Lỗi: lớp con dùng thành viên private của lớp cha",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\n    long long soDu = 0;\npublic:\n    long long laySoDu() const {\n        return soDu;\n    }\n};\n\nclass TietKiem : public TaiKhoan {\npublic:\n    void tangLai() {\n        soDu += 100;\n    }\n};\n\nint main() {\n    TietKiem t;\n    t.tangLai();\n    cout << t.laySoDu() << \"\\n\";\n    return 0;\n}"}];
const sim34=makeSim2(document.getElementById("sim-l34"),{id:"s34",presets:P34});
makeEx2(document.getElementById("ex-l34"),sim34,[{t:"Hình tròn kế thừa Hình",d:"Viết lớp <code>Hinh<\/code> có thành viên protected <code>string ten<\/code>, hàm tạo <code>Hinh(string t)<\/code> và hàm <code>void inTen() const<\/code> in tên. Lớp <code>HinhTron : public Hinh<\/code> có bán kính r, hàm tạo <code>HinhTron(double r)<\/code> gọi <code>Hinh(\"Hinh tron\")<\/code>, và <code>double dienTich() const<\/code> (π = 3.14159). Nhập r, in tên rồi diện tích với 2 chữ số thập phân trên dòng tiếp theo.",tests:[{in:"1",out:"Hinh tron\n3.14"},{in:"2.5",out:"Hinh tron\n19.63"},{in:"0",out:"Hinh tron\n0.00"}],start:"#include <iostream>\n#include <iomanip>\n#include <string>\nusing namespace std;\n\nclass Hinh {\nprotected:\n    string ten;\npublic:\n    Hinh(string t) : ten(t) {}\n    void inTen() const {\n        cout << ten << \"\\n\";\n    }\n};\n\nclass HinhTron : public Hinh {\n    double r;\npublic:\n    // hàm tạo HinhTron(double r) gọi Hinh(\"Hinh tron\")\n    // double dienTich() const\n};\n\nint main() {\n    double r;\n    cin >> r;\n    HinhTron h(r);\n    h.inTen();\n    cout << fixed << setprecision(2) << h.dienTich() << \"\\n\";\n    return 0;\n}",need:/class\s+HinhTron\s*:\s*public\s+Hinh[\s\S]*HinhTron\s*\(\s*double\s+\w+\s*\)\s*:\s*Hinh\s*\(/,needMsg:"Hãy giữ class HinhTron : public Hinh và gọi Hinh(...) trong danh sách khởi tạo của hàm tạo HinhTron(double)."},{t:"Nhân viên và quản lý",d:"Nhập n (1 ≤ n ≤ 100) rồi n dòng: <code>NV ten luong<\/code> hoặc <code>QL ten luong phucap<\/code> (số nguyên). Viết lớp <code>NhanVien<\/code> (ten, luong, <code>long long thuNhap() const<\/code>) và <code>QuanLy : public NhanVien<\/code> có phucap, viết lại <code>thuNhap()<\/code> bằng <code>NhanVien::thuNhap() + phucap<\/code>. Lưu vào <code>vector&lt;NhanVien&gt;<\/code> và <code>vector&lt;QuanLy&gt;<\/code>. In từng người theo thứ tự nhập dạng <code>ten thuNhap<\/code>, cuối cùng in tổng thu nhập.",tests:[{in:"3\nNV An 10\nQL Ha 20 5\nNV Binh 12",out:"An 10\nHa 25\nBinh 12\n47"},{in:"1\nQL Tu 100 0",out:"Tu 100\n100"},{in:"2\nNV A 1000000000\nQL B 1000000000 1000000000",out:"A 1000000000\nB 2000000000\n3000000000"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass NhanVien {\nprotected:\n    string ten;\n    long long luong;\npublic:\n    NhanVien(string t, long long l) : ten(t), luong(l) {}\n    string layTen() const { return ten; }\n    long long thuNhap() const { return luong; }\n};\n\nclass QuanLy : public NhanVien {\n    long long phuCap;\npublic:\n    // hàm tạo, thuNhap()\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<NhanVien> nv;\n    vector<QuanLy> ql;\n    vector<int> loai, viTri;   // ghi lại thứ tự nhập: loại (0 = NV, 1 = QL) và vị trí trong vector tương ứng\n    for (int i = 0; i < n; i++) {\n        string k, t;\n        long long l;\n        cin >> k >> t >> l;\n        // đọc thêm phucap nếu là QL, thêm vào vector phù hợp\n    }\n    long long tong = 0;\n    // in theo thứ tự nhập, cộng dồn tổng\n    cout << tong << \"\\n\";\n    return 0;\n}",need:/class\s+QuanLy\s*:\s*public\s+NhanVien[\s\S]*NhanVien\s*::\s*thuNhap\s*\(\s*\)/,needMsg:"Hãy viết QuanLy kế thừa public NhanVien và gọi NhanVien::thuNhap() trong QuanLy::thuNhap()."},{t:"Tài khoản tiết kiệm",d:"Lớp <code>TaiKhoan<\/code> có <code>soDu<\/code> protected (long long), <code>nap<\/code>, <code>rut<\/code> (rút quá số dư thì từ chối), <code>laySoDu() const<\/code>. Lớp <code>TietKiem : public TaiKhoan<\/code> có lãi suất theo phần nghìn mỗi tháng (số nguyên k ‰) và hàm <code>cuoiThang()<\/code> cộng lãi <code>soDu * k / 1000<\/code> (chia nguyên). Dòng 1: số dư ban đầu s và k; dòng 2: số lệnh q; dòng 3: q lệnh, mỗi lệnh là một số nguyên: số dương là nạp, số âm là rút (lấy trị tuyệt đối), 0 là hết tháng. In số dư cuối và số lần rút bị từ chối.",tests:[{in:"1000 5\n4\n0 -2000 500 0",out:"1512 1"},{in:"0 10\n3\n100 0 -110",out:"101 1"},{in:"1000000000 1\n2\n0 0",out:"1002001000 0"}],start:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass TaiKhoan {\nprotected:\n    long long soDu;\npublic:\n    TaiKhoan(long long s) : soDu(s) {}\n    void nap(long long t) { soDu += t; }\n    bool rut(long long t) {\n        if (t > soDu) return false;\n        soDu -= t;\n        return true;\n    }\n    long long laySoDu() const { return soDu; }\n};\n\nclass TietKiem : public TaiKhoan {\n    long long k;\npublic:\n    // hàm tạo TietKiem(long long s, long long kk), hàm cuoiThang()\n};\n\nint main() {\n    long long s, k;\n    int q;\n    cin >> s >> k >> q;\n    TietKiem t(s, k);\n    int tuChoi = 0;\n    for (int i = 0; i < q; i++) {\n        long long x;\n        cin >> x;\n        // x > 0: nạp; x < 0: rút -x; x == 0: cuối tháng\n    }\n    cout << t.laySoDu() << \" \" << tuChoi << \"\\n\";\n    return 0;\n}",need:/class\s+TietKiem\s*:\s*public\s+TaiKhoan[\s\S]*void\s+cuoiThang\s*\(\s*\)/,needMsg:"Hãy viết class TietKiem : public TaiKhoan có hàm void cuoiThang()."}]);

makeQuiz("quiz34","score34",[{"q": "Khi nào nên dùng kế thừa giữa hai lớp A (cha) và B (con)?", "o": ["Khi B có một A bên trong", "Khi “B là một A” đúng", "Khi A và B có tên giống nhau", "Bất cứ khi nào muốn dùng lại mã"], "a": 1, "e": "Kế thừa thể hiện quan hệ “là một”. Quan hệ “có một” dùng thành viên."}, {"q": "Thành viên <code>protected<\/code> của lớp cha dùng được ở đâu?", "o": ["Chỉ trong lớp cha", "Trong lớp cha và các lớp con", "Ở mọi nơi", "Chỉ trong main"], "a": 1, "e": "protected: lớp cha và lớp con dùng được, bên ngoài thì không."}, {"q": "Tạo một đối tượng lớp con Con : public Cha. Thứ tự chạy là gì?", "o": ["Hàm tạo Con rồi Cha; hủy Con rồi Cha", "Hàm tạo Cha rồi Con; hủy Con rồi Cha", "Hàm tạo Cha rồi Con; hủy Cha rồi Con", "Chỉ chạy hàm tạo của Con"], "a": 1, "e": "Xây từ lớp cha lên, hủy theo thứ tự ngược lại."}, {"q": "<code>Cha* p = &amp;con;<\/code> và cả Cha, Con đều có hàm thường (không virtual) <code>f()<\/code>. <code>p-&gt;f()<\/code> gọi hàm nào?", "o": ["Con::f()", "Cha::f()", "Cả hai", "Lỗi biên dịch"], "a": 1, "e": "Không có virtual thì hàm được chọn theo kiểu của con trỏ (Cha), không theo đối tượng thật."}]);

